window.addEventListener('scroll', () => {
  nav.classList.toggle('scrolled', window.scrollY > 40);
}, { passive: true });

// ----- Full-screen menu -----
(function () {
  const ham = document.getElementById('hamburger');
  const drawer = document.getElementById('drawer');
  const close = document.getElementById('drawer-close');
  const backdrop = document.getElementById('mega-backdrop');
  function open() { drawer.classList.add('open'); drawer.setAttribute('aria-hidden','false'); ham.classList.add('open'); backdrop.classList.add('open'); document.body.style.overflow = 'hidden'; }
  function closeD() { drawer.classList.remove('open'); drawer.setAttribute('aria-hidden','true'); ham.classList.remove('open'); backdrop.classList.remove('open'); document.body.style.overflow = ''; }
  ham.addEventListener('click', () => drawer.classList.contains('open') ? closeD() : open());
  close.addEventListener('click', closeD);
  backdrop.addEventListener('click', closeD);
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && drawer.classList.contains('open')) closeD(); });
})();

