const fmt = (n) => '₹ ' + n.toLocaleString('en-IN');

// ----- Filter state -----
const state = { category: 'all', metal: [], occasion: [], priceMin: null, priceMax: null, sort: 'featured', shown: 9 };

const grid = document.getElementById('productGrid');
const resultCount = document.getElementById('resultCount');
const loadMeta = document.getElementById('loadMeta');
const loadMore = document.getElementById('loadMore');
const loadWrap = document.querySelector('.load-more-wrap');

function filtered() {
  let list = PRODUCTS.filter(p => {
    if (state.category !== 'all' && p.cat !== state.category) return false;
    if (state.metal.length && !state.metal.some(m => p.metal.includes(m))) return false;
    if (state.occasion.length && !state.occasion.some(o => p.occ.includes(o))) return false;
    if (state.priceMin != null && p.price < state.priceMin) return false;
    if (state.priceMax != null && p.price > state.priceMax) return false;
    return true;
  });
  switch (state.sort) {
    case 'new':    list = list.slice().sort((a,b) => b.new - a.new); break;
    case 'low':    list = list.slice().sort((a,b) => a.price - b.price); break;
    case 'high':   list = list.slice().sort((a,b) => b.price - a.price); break;
    case 'rating': list = list.slice().sort((a,b) => b.rating - a.rating || b.reviews - a.reviews); break;
  }
  return list;
}

function cardHTML(p) {
  return `
    <div class="product reveal">
      <div class="imgbox">
        ${p.badge ? `<span class="badge">${p.badge}</span>` : ''}
        <button class="wishlist" aria-label="Add to wishlist">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M12 21s-7-4.5-9.5-9A5.5 5.5 0 0 1 12 6a5.5 5.5 0 0 1 9.5 6c-2.5 4.5-9.5 9-9.5 9Z"/></svg>
        </button>
        <img class="ph-img" src="${p.img}" alt="${p.name}" loading="lazy" onerror="this.style.opacity=0" />
        <img class="ph-img alt" src="${p.alt}" alt="${p.name} alternate" loading="lazy" onerror="this.style.display='none'" />
        <button class="quick-add" data-qv="${p.name}">Quick view</button>
      </div>
      <div class="info">
        <div>
          <h4 class="name"><a href="product.html">${p.name}</a></h4>
          <div class="karat">${p.karat}</div>
          <div class="rating"><span class="stars">${'★'.repeat(p.rating)}${'☆'.repeat(5-p.rating)}</span> · ${p.reviews} reviews</div>
        </div>
        <div class="price">${fmt(p.price)}</div>
      </div>
    </div>`;
}

const bannerHTML = `
  <a class="grid-banner reveal" href="#" style="text-decoration:none;">
    <img src="https://images.unsplash.com/photo-1535556116002-6281ff3e9f36?w=1600&h=540&fit=crop&auto=format&q=80" alt="Festive Edit" />
    <div class="ov">
      <span class="eyebrow">Festive Edit · MMXXVI</span>
      <h3>Made for the <em>season</em> of light.</h3>
      <span>Explore the edit →</span>
    </div>
  </a>`;

function render() {
  const list = filtered();
  resultCount.textContent = list.length;
  const visible = list.slice(0, state.shown);

  let html = '';
  visible.forEach((p, i) => {
    html += cardHTML(p);
    if (i === 5) html += bannerHTML; // insert editorial banner after 6th card
  });
  grid.innerHTML = html || `<p style="grid-column:1/-1;color:var(--ink-soft);padding:40px 0;">No pieces match these filters. <button id="resetInline" style="color:var(--gold);border-bottom:1px solid var(--gold);">Clear filters</button></p>`;

  loadMeta.textContent = `Showing ${Math.min(state.shown, list.length)} of ${list.length}`;
  loadWrap.style.display = list.length > state.shown ? 'block' : (list.length === 0 ? 'none' : 'none');
  if (list.length > 0 && state.shown >= list.length) loadWrap.style.display = 'none';

  // reveal + wishlist
  requestAnimationFrame(() => grid.querySelectorAll('.reveal').forEach(el => el.classList.add('in')));
  grid.querySelectorAll('.wishlist').forEach(w => w.addEventListener('click', (e) => { e.preventDefault(); w.classList.toggle('active'); }));
  grid.querySelectorAll('.quick-add[data-qv]').forEach(b => b.addEventListener('click', (e) => { e.preventDefault(); openQV(b.dataset.qv); }));
  const reset = document.getElementById('resetInline');
  if (reset) reset.addEventListener('click', clearAll);
}

// ----- Filter UI -----
document.querySelectorAll('[data-filter]').forEach(group => {
  const key = group.dataset.filter;
  group.querySelectorAll('.opt').forEach(opt => {
    opt.addEventListener('click', () => {
      const val = opt.dataset.value;
      if (key === 'category') {
        group.querySelectorAll('.opt').forEach(o => o.classList.remove('checked'));
        opt.classList.add('checked');
        state.category = val;
      } else {
        opt.classList.toggle('checked');
        const arr = key === 'metal' ? state.metal : state.occasion;
        const idx = arr.indexOf(val);
        if (idx >= 0) arr.splice(idx, 1); else arr.push(val);
      }
      state.shown = 9;
      render();
    });
  });
});

document.getElementById('priceMin').addEventListener('input', (e) => { state.priceMin = e.target.value ? +e.target.value : null; state.shown = 9; render(); });
document.getElementById('priceMax').addEventListener('input', (e) => { state.priceMax = e.target.value ? +e.target.value : null; state.shown = 9; render(); });
document.getElementById('sortSelect').addEventListener('change', (e) => { state.sort = e.target.value; render(); });
loadMore.addEventListener('click', () => { state.shown += 6; render(); });

function clearAll() {
  state.category = 'all'; state.metal = []; state.occasion = []; state.priceMin = null; state.priceMax = null; state.shown = 9;
  document.querySelectorAll('[data-filter="category"] .opt').forEach((o,i) => o.classList.toggle('checked', i === 0));
  document.querySelectorAll('[data-filter="metal"] .opt, [data-filter="occasion"] .opt').forEach(o => o.classList.remove('checked'));
  document.getElementById('priceMin').value = '';
  document.getElementById('priceMax').value = '';
  render();
}
document.getElementById('filterClear').addEventListener('click', clearAll);

// ----- Mobile filters drawer -----
const filters = document.getElementById('filters');
const fBackdrop = document.getElementById('filtersBackdrop');
document.getElementById('filterToggle').addEventListener('click', () => { filters.classList.add('open'); fBackdrop.classList.add('open'); document.body.style.overflow = 'hidden'; });
function closeFilters() { filters.classList.remove('open'); fBackdrop.classList.remove('open'); document.body.style.overflow = ''; }
document.getElementById('filtersClose').addEventListener('click', closeFilters);
fBackdrop.addEventListener('click', closeFilters);

// ----- Quick view -----
const qv = document.getElementById('qv');
const qvBackdrop = document.getElementById('qvBackdrop');
function openQV(name) {
  const p = PRODUCTS.find(x => x.name === name);
  if (!p) return;
  document.getElementById('qvImg').src = p.img;
  document.getElementById('qvImg').alt = p.name;
  document.getElementById('qvName').textContent = p.name;
  document.getElementById('qvKarat').textContent = p.karat;
  document.getElementById('qvStars').textContent = '★'.repeat(p.rating) + '☆'.repeat(5 - p.rating);
  document.getElementById('qvReviews').textContent = '· ' + p.reviews + ' reviews';
  document.getElementById('qvPrice').textContent = fmt(p.price);
  qv.classList.add('open');
  qv.setAttribute('aria-hidden', 'false');
  qvBackdrop.classList.add('open');
  document.body.style.overflow = 'hidden';
}
function closeQV() {
  qv.classList.remove('open');
  qv.setAttribute('aria-hidden', 'true');
  qvBackdrop.classList.remove('open');
  document.body.style.overflow = '';
}
document.getElementById('qvClose').addEventListener('click', closeQV);
qvBackdrop.addEventListener('click', closeQV);
qv.addEventListener('click', (e) => { if (e.target === qv) closeQV(); });
document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && qv.classList.contains('open')) closeQV(); });

render();
